pub fn find(id: []const u8) ?Yaku {
    for (all) |yaku| if (std.mem.eql(u8, id, yaku.id)) return yaku;
    return null;
}
test "catalog IDs and lookup" {
    try std.testing.expect(find("pinfu") != null);
    try std.testing.expect(find("unknown") == null);
    for (all, 0..) |yaku, i| {
        try std.testing.expect(yaku.example.len >= 14 and yaku.example.len <= 18);
        var counts: [34]u8 = @splat(0);
        for (yaku.example) |tile| {
            try std.testing.expect(tile.validate());
            counts[tile.index()] += 1;
        }
        for (counts) |count| try std.testing.expect(count <= 4);
        for (all[0..i]) |other| try std.testing.expect(!std.mem.eql(u8, other.id, yaku.id));
    }
}
